def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    bob_like_bid = None
    high_bid = 0.0
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) > high_bid:
                    high_bid = float(bid)
                if agent_id == 'Bob':
                    bob_like_bid = float(bid)

    if budget <= 0:
        return 0.0

    winners_capacity = int(supply // WATER_REQ)
    alive_count = len(alive) + 1
    scarcity = alive_count - winners_capacity

    if not alive:
        return float(min(budget, 21.0))

    threat_bid = bob_like_bid if bob_like_bid is not None else (max(prev_bids) if prev_bids else 45.0)

    emergency = hp <= 3 or no_water_days >= 2
    pressured = hp <= 5 or no_water_days >= 1

    if winners_capacity >= 2:
        if emergency:
            bid = max(56.0, threat_bid + 2.0)
        elif pressured:
            bid = max(44.0, min(55.0, threat_bid + 1.0))
        else:
            bid = 31.0 if high_bid >= 80.0 else 36.0
    else:
        if emergency:
            bid = max(68.0, threat_bid + 6.0)
        elif pressured:
            bid = max(58.0, threat_bid + 3.0)
        else:
            bid = max(50.0, threat_bid + 1.5)

    if day >= 8:
        bid += 4.0
    if day >= 9 and pressured:
        bid += 6.0

    reserve_floor = 0.0
    days_left = max(0, 10 - day)
    if not emergency and days_left > 0:
        reserve_floor = min(budget * 0.35, days_left * 18.0)

    max_affordable = max(0.0, budget - reserve_floor)
    if emergency:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # If we are already in danger, bid aggressively.
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from trace for immediate reaction.
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many full water units the supply can cover.
    # (We only use it to scale bids; indices not needed.)
    capacity_units = max(1.0, supply / float(WATER_REQ))

    # Core strategy:
    # - If Cindy likely keeps bidding near 90 (survived with max bid), we bid slightly below/around 90.
    # - If yesterday saw extreme low bids (others died), we still bid enough to secure water.
    # - If our hp is low or no_water_days is high, we increase bid.

    # Identify Cindy's yesterday bid if present.
    cindy_prev = None
    for opp_id, opp in alive_opps:
        if str(opp_id) == 'Cindy':
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    cindy_prev = float(prev['bid'])
                except Exception:
                    cindy_prev = None

    # Base target bid
    if cindy_prev is not None and cindy_prev >= DAILY_SALARY * 0.95:
        target = DAILY_SALARY * 0.88  # try to beat her without maxing out
    elif highest_prev_bid >= DAILY_SALARY * 0.85:
        target = min(DAILY_SALARY * 0.90, highest_prev_bid - 1.0)
    else:
        # Mid pressure: bid enough to secure, but conserve budget.
        target = max(DAILY_SALARY * 0.55, (highest_prev_bid + 5.0) if highest_prev_bid > 0 else DAILY_SALARY * 0.60)

    # Risk adjustment
    if hp <= 2.0:
        target = max(target, DAILY_SALARY * 0.95)
    elif hp <= 4.0:
        target = max(target, DAILY_SALARY * 0.80)

    if no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.85)

    # Budget constraint and slight day-based taper to avoid running out by episode end.
    # episode_days is fixed at 10 in meta, so day 1-10: taper near end.
    # Use day only for small adjustment.
    taper = 1.0
    if day >= 8:
        taper = 0.95
    if day >= 9:
        taper = 0.90

    bid = min(budget, target * taper)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0
    return float(bid)

